const webhookBody = $('M3 Run (webhook)').item.json.body;
const transcribe = $json;
return [{ json: {
  event_slug: webhookBody.event_slug,
  run_id: transcribe.run_id,
  images: webhookBody.images,
  clips: webhookBody.clips
} }];

const webhookBody = $json.body;
return [{ json: {
  event_slug: webhookBody.event_slug,
  run_id: null,
  images: webhookBody.images,
  clips: webhookBody.clips
} }];

const file = $('Batch Files (1)').item.json;
const uploaded = $json;
return [{ json: {
  name: file.name,
  drive_file_id: uploaded.id || null,
  web_view_link: uploaded.webViewLink || null
} }];

const files = $('Map Drive Upload Result').all().map(i => i.json);
const folder = $('Create Drive Folder').item.json;
return [{ json: {
  run_id: $('Call Module API - Run').item.json.run_id,
  folder_id: folder.id,
  folder_url: folder.webViewLink || null,
  files
} }];

const runResp = $('Call Module API - Run').item.json;
const recordResp = $json;
const runSummary = runResp.summary || {};
const drive = $('Aggregate Drive Uploads').item.json;

const receipts = [].concat(runResp.receipts || [], recordResp.receipts || []);

const summary = {
  run_id: recordResp.run_id || runResp.run_id,
  blog_words: runSummary.blog_words ?? null,
  chapters: runSummary.chapters ?? null,
  posts: runSummary.posts ?? null,
  images: runSummary.images ?? null,
  clips: runSummary.clips ?? null,
  grounding: runSummary.grounding ?? null,
  drive_folder_url: drive.folder_url ?? null,
  files_uploaded: (drive.files || []).length,
  receipts
};

const fileName = summary.run_id + '-m3.json';
const fileContent = Buffer.from(JSON.stringify(summary, null, 2), 'utf8').toString('base64');

return [{ json: summary, binary: { data: { data: fileContent, mimeType: 'application/json', fileName: fileName } } }];
